require_once dirname(__DIR__,3).'/neptune_secure/bootstrap.php';$u=require_role(['owner','admin','strategy']);$org=$u['organization_id'];$msg='';
$s=$pdo->prepare('SELECT * FROM teams WHERE organization_id=? ORDER BY frc_team_number');$s->execute([$org]);$mine=$s->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$recipient=(int)$_POST['recipient_team_number'];$s=$pdo->prepare('SELECT id FROM teams WHERE frc_team_number=? ORDER BY id LIMIT 1');$s->execute([$recipient]);$rid=$s->fetchColumn();if(!$rid){$msg='Recipient team must already have a Neptune team account.';}else{$q='INSERT INTO sharing_relationships(owner_team_id,recipient_team_id,status,share_match_data,share_pit_data,share_notes,share_raw_actions,share_analytics) VALUES(?,?,\'active\',?,?,?,?,?) ON DUPLICATE KEY UPDATE status=\'active\',share_match_data=VALUES(share_match_data),share_pit_data=VALUES(share_pit_data),share_notes=VALUES(share_notes),share_raw_actions=VALUES(share_raw_actions),share_analytics=VALUES(share_analytics)';$pdo->prepare($q)->execute([(int)$_POST['owner_team_id'],$rid,isset($_POST['match']),isset($_POST['pit']),isset($_POST['notes']),isset($_POST['raw']),isset($_POST['analytics'])]);$msg='Sharing permissions saved.';}}
$q='SELECT sr.*,a.frc_team_number owner_num,b.frc_team_number recipient_num FROM sharing_relationships sr JOIN teams a ON a.id=sr.owner_team_id JOIN teams b ON b.id=sr.recipient_team_id WHERE a.organization_id=? ORDER BY a.frc_team_number,b.frc_team_number';$s=$pdo->prepare($q);$s->execute([$org]);$rels=$s->fetchAll();$pageTitle='Data Sharing';include dirname(__DIR__).'/partials_header.php';?>
<h1>Data Sharing</h1><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif;?><div class="card"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="grid"><div><label>Our team</label><select name="owner_team_id"><?php foreach($mine as $t):?><option value="<?=$t['id']?>">#<?=e($t['frc_team_number'])?></option><?php endforeach;?></select></div><div><label>Recipient FRC team number</label><input type="number" name="recipient_team_number" required></div></div><div class="toolbar"><label><input style="width:auto" type="checkbox" name="match" checked> Match data</label><label><input style="width:auto" type="checkbox" name="raw" checked> Raw actions</label><label><input style="width:auto" type="checkbox" name="analytics" checked> Analytics</label><label><input style="width:auto" type="checkbox" name="pit"> Pit</label><label><input style="width:auto" type="checkbox" name="notes"> Notes</label></div><button>Save sharing</button></form></div><div class="card" style="margin-top:16px"><h2>Active relationships</h2><table class="table"><tr><th>Owner</th><th>Recipient</th><th>Raw</th><th>Pit</th><th>Notes</th></tr><?php foreach($rels as $r):?><tr><td>#<?=$r['owner_num']?></td><td>#<?=$r['recipient_num']?></td><td><?=$r['share_raw_actions']?'Yes':'No'?></td><td><?=$r['share_pit_data']?'Yes':'No'?></td><td><?=$r['share_notes']?'Yes':'No'?></td></tr><?php endforeach;?></table></div><?php include dirname(__DIR__).'/partials_footer.php';
